//! The Llamble AI bot. Replies are generated by llama.cpp, either on a member's PC
//! (a "GPU worker" that opted in from the desktop app) or on a llama.cpp server
//! running next to Llamble. Workers are preferred; the server is the fallback.
use crate::error::{now_ms, new_id, ApiResult};
use crate::models::{load_message, load_users, Channel, MessageRow, MSG_COLS};
use crate::perms;
use crate::state::{AuthUser, Shared};
use axum::extract::{Path, State};
use axum::Json;
use dashmap::DashMap;
use futures::StreamExt;
use once_cell::sync::Lazy;
use regex::Regex;
use serde::Deserialize;
use serde_json::{json, Value};
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::mpsc::{unbounded_channel, UnboundedReceiver, UnboundedSender};
use tokio::sync::Mutex;

pub struct Worker {
    pub user_id: String,
    pub tx: UnboundedSender<String>,
    pub gpu: String,
    pub vram_mb: i64,
    pub model: String,
    pub active: usize,
    /// false while the lender is using their PC (not idle) or gaming (GPU busy)
    pub available: bool,
    pub reason: String,
}

pub enum JobMsg {
    Chunk(String),
    /// the model wants tools run (OpenAI-style tool_calls)
    Tools(Vec<Value>),
    Done,
    Error(String),
}

/// Each person's time zone, as their app reports it (for "what time is it").
pub static USER_TZ: once_cell::sync::Lazy<dashmap::DashMap<String, String>> = once_cell::sync::Lazy::new(Default::default);

pub fn note_tz(uid: &str, headers: &axum::http::HeaderMap) {
    if let Some(tz) = headers.get("x-tz").and_then(|v| v.to_str().ok()) {
        if tz.len() < 64 && tz.chars().all(|c| c.is_ascii_alphanumeric() || "/_-+".contains(c)) {
            USER_TZ.insert(uid.to_string(), tz.to_string());
        }
    }
}

#[derive(Default)]
pub struct BotRuntime {
    /// keyed by gateway connection id
    pub workers: DashMap<u64, Worker>,
    /// job id -> (worker conn id, sink)
    pub jobs: DashMap<String, (u64, UnboundedSender<JobMsg>)>,
    channel_locks: DashMap<String, Arc<Mutex<()>>>,
}

pub async fn ensure_bot_user(db: &sqlx::SqlitePool, name: &str) -> anyhow::Result<String> {
    if let Some(id) = sqlx::query_scalar::<_, String>("SELECT id FROM users WHERE is_bot = 1 LIMIT 1").fetch_optional(db).await? {
        sqlx::query("UPDATE users SET display_name = ? WHERE id = ?").bind(name).bind(&id).execute(db).await?;
        return Ok(id);
    }
    let id = new_id();
    sqlx::query("INSERT INTO users (id, username, display_name, password_hash, is_admin, is_bot, created_at) VALUES (?, 'llamble-bot', ?, '!', 0, 1, ?)")
        .bind(&id)
        .bind(name)
        .bind(now_ms())
        .execute(db)
        .await?;
    Ok(id)
}

// ---------- settings ----------

#[derive(Debug, Clone)]
pub struct BotSettings {
    pub enabled: bool,
    pub system_prompt: String,
    pub always_channels: Vec<String>,
    /// "Hey Llamble" in this server's voice channels
    pub voice_listen: bool,
}

pub async fn settings(state: &Shared, guild_id: &str) -> BotSettings {
    let row: Option<(bool, String, String, bool)> =
        sqlx::query_as("SELECT enabled, system_prompt, always_channels, voice_listen FROM bot_settings WHERE guild_id = ?")
            .bind(guild_id)
            .fetch_optional(&state.db)
            .await
            .ok()
            .flatten();
    match row {
        Some((enabled, system_prompt, ch, voice_listen)) => BotSettings {
            enabled,
            system_prompt,
            always_channels: serde_json::from_str(&ch).unwrap_or_default(),
            voice_listen,
        },
        None => BotSettings { enabled: false, system_prompt: String::new(), always_channels: vec![], voice_listen: false },
    }
}

fn settings_json(state: &Shared, s: &BotSettings) -> Value {
    json!({
        "enabled": s.enabled,
        "system_prompt": s.system_prompt,
        "always_channels": s.always_channels,
        "voice_listen": s.voice_listen,
        "bot_user_id": state.bot_id,
        "bot_name": state.s().bot_name,
    })
}

pub async fn get_settings(State(state): State<Shared>, auth: AuthUser, Path(gid): Path<String>) -> ApiResult<Json<Value>> {
    perms::require_guild(&state.db, &gid, &auth.id, perms::VIEW).await?;
    let s = settings(&state, &gid).await;
    Ok(Json(settings_json(&state, &s)))
}

#[derive(Deserialize)]
pub struct UpdateSettings {
    pub enabled: Option<bool>,
    pub system_prompt: Option<String>,
    pub always_channels: Option<Vec<String>>,
}

pub async fn update_settings(State(state): State<Shared>, auth: AuthUser, Path(gid): Path<String>, Json(req): Json<UpdateSettings>) -> ApiResult<Json<Value>> {
    perms::require_guild(&state.db, &gid, &auth.id, perms::MANAGE_GUILD).await?;
    let mut s = settings(&state, &gid).await;
    let was = s.enabled;
    if let Some(e) = req.enabled {
        s.enabled = e;
    }
    if let Some(p) = req.system_prompt {
        s.system_prompt = p.chars().take(4000).collect();
    }
    if let Some(c) = req.always_channels {
        s.always_channels = c.into_iter().take(50).collect();
    }
    sqlx::query("INSERT OR REPLACE INTO bot_settings (guild_id, enabled, system_prompt, always_channels, voice_listen) VALUES (?,?,?,?,?)")
        .bind(&gid)
        .bind(s.enabled)
        .bind(&s.system_prompt)
        .bind(serde_json::to_string(&s.always_channels).unwrap())
        .bind(s.voice_listen)
        .execute(&state.db)
        .await?;
    if s.enabled && !was {
        crate::api::guilds::add_member(&state, &gid, &state.bot_id).await?;
    } else if !s.enabled && was {
        let members = crate::state::guild_member_ids(&state.db, &gid).await;
        sqlx::query("DELETE FROM members WHERE guild_id = ? AND user_id = ?").bind(&gid).bind(&state.bot_id).execute(&state.db).await?;
        state.hub.send_users(&members, "GUILD_MEMBER_REMOVE", &json!({ "guild_id": gid, "user_id": state.bot_id }));
    }
    if s.enabled != was {
        crate::voicebot::announce_config(&state).await;
    }
    let v = settings_json(&state, &s);
    state.emit_guild(&gid, "BOT_SETTINGS_UPDATE", &json!({ "guild_id": gid, "settings": v })).await;
    Ok(Json(v))
}

pub async fn status(State(state): State<Shared>, _auth: AuthUser) -> ApiResult<Json<Value>> {
    let mut workers: Vec<Value> = vec![];
    for w in state.bot.workers.iter() {
        workers.push(json!({ "user_id": w.user_id, "gpu": w.gpu, "vram_mb": w.vram_mb, "model": w.model, "active_jobs": w.active, "available": w.available, "reason": w.reason }));
    }
    Ok(Json(json!({
        "bot_user_id": state.bot_id,
        "bot_name": state.s().bot_name,
        "server_backend": crate::ai::server_llama_url(&state).await.is_some(),
        "server_model": state.ai.snapshot().await,
        "worker_policy": gpu_policy(&state).await,
        "workers": workers,
    })))
}

// ---------- worker registration (called from the gateway) ----------

/// Who may lend a GPU: "off" | "admins" | "members". Admin-controlled; env sets the default.
pub async fn gpu_policy(state: &Shared) -> String {
    sqlx::query_scalar::<_, String>("SELECT value FROM settings WHERE key = 'gpu.lending'")
        .fetch_optional(&state.db)
        .await
        .ok()
        .flatten()
        .unwrap_or_else(|| state.cfg.bot_workers.clone())
}

pub async fn worker_eligible(state: &Shared, user_id: &str) -> bool {
    let policy = gpu_policy(state).await;
    if policy == "off" {
        return false;
    }
    if policy == "members" {
        return true;
    }
    sqlx::query_scalar::<_, bool>("SELECT is_admin FROM users WHERE id = ?")
        .bind(user_id)
        .fetch_optional(&state.db)
        .await
        .ok()
        .flatten()
        .unwrap_or(false)
}

pub fn worker_gone(state: &Shared, conn: u64) {
    if state.bot.workers.remove(&conn).is_some() {
        // fail any in-flight jobs on that worker so they fall back
        let dead: Vec<String> = state.bot.jobs.iter().filter(|j| j.value().0 == conn).map(|j| j.key().clone()).collect();
        for id in dead {
            if let Some((_, (_, tx))) = state.bot.jobs.remove(&id) {
                let _ = tx.send(JobMsg::Error("worker disconnected".into()));
            }
        }
    }
}

pub fn job_event(state: &Shared, conn: u64, v: &Value) {
    let Some(job) = v["job_id"].as_str() else { return };
    let Some(entry) = state.bot.jobs.get(job) else { return };
    if entry.0 != conn {
        return; // only the assigned worker may answer
    }
    let msg = match v["op"].as_str() {
        Some("job_chunk") => JobMsg::Chunk(v["text"].as_str().unwrap_or("").to_string()),
        Some("job_tools") => JobMsg::Tools(v["calls"].as_array().cloned().unwrap_or_default()),
        Some("job_done") => JobMsg::Done,
        _ => JobMsg::Error(v["error"].as_str().unwrap_or("worker error").to_string()),
    };
    let _ = entry.1.send(msg);
}

// ---------- admin: GPU sharing ----------

pub async fn get_gpu_pool(State(state): State<Shared>, auth: AuthUser) -> ApiResult<Json<Value>> {
    if !auth.is_master {
        return Err(crate::error::AppError::forbidden());
    }
    let mut rows: Vec<(String, String, i64, String, bool, String, usize)> = state
        .bot
        .workers
        .iter()
        .map(|w| (w.user_id.clone(), w.gpu.clone(), w.vram_mb, w.model.clone(), w.available, w.reason.clone(), w.active))
        .collect();
    rows.sort_by(|a, b| b.4.cmp(&a.4).then(b.2.cmp(&a.2)));
    let ids: Vec<String> = rows.iter().map(|r| r.0.clone()).collect();
    let users = load_users(&state.db, &ids).await?;
    let first_available = rows.iter().position(|r| r.4);
    let workers: Vec<Value> = rows
        .iter()
        .enumerate()
        .map(|(i, (uid, gpu, vram, model, avail, reason, active))| {
            json!({
                "user_id": uid,
                "name": users.get(uid).map(|u| u.display_name.clone()),
                "gpu": gpu, "vram_mb": vram, "model": model,
                "available": avail, "reason": reason, "active_jobs": active,
                "in_use": Some(i) == first_available,
            })
        })
        .collect();
    Ok(Json(json!({
        "policy": gpu_policy(&state).await,
        "workers": workers,
        "server_model": state.ai.snapshot().await,
    })))
}

#[derive(Deserialize)]
pub struct GpuPolicy {
    pub policy: String,
}

pub async fn set_gpu_policy(State(state): State<Shared>, auth: AuthUser, Json(req): Json<GpuPolicy>) -> ApiResult<Json<Value>> {
    if !auth.is_master {
        return Err(crate::error::AppError::forbidden());
    }
    if !["off", "admins", "members"].contains(&req.policy.as_str()) {
        return Err(crate::error::AppError::bad("policy must be off, admins or members"));
    }
    sqlx::query("INSERT OR REPLACE INTO settings (key, value) VALUES ('gpu.lending', ?)")
        .bind(&req.policy)
        .execute(&state.db)
        .await?;
    // drop lenders that are no longer allowed
    let conns: Vec<(u64, String)> = state.bot.workers.iter().map(|w| (*w.key(), w.user_id.clone())).collect();
    for (conn, uid) in conns {
        if !worker_eligible(&state, &uid).await {
            if let Some(w) = state.bot.workers.get(&conn) {
                let _ = w.tx.send(json!({ "t": "WORKER_REJECTED", "d": { "reason": rejection_reason(&req.policy) } }).to_string());
            }
            worker_gone(&state, conn);
        }
    }
    Ok(Json(json!({ "policy": req.policy })))
}

pub fn rejection_reason(policy: &str) -> &'static str {
    if policy == "off" {
        "The server admin has turned off GPU sharing."
    } else {
        "Only server admins can lend a GPU on this server."
    }
}

// ---------- triggering ----------

fn name_call_re(name: &str) -> Regex {
    Regex::new(&format!(r"(?i)^\s*(?:(?:hey|hi|yo|ok|okay|hello)[\s,]+)?@?{}\b", regex::escape(name))).unwrap()
}

/// Plain-language reason the server's own model can't answer right now.
async fn server_model_problem(state: &Shared) -> String {
    let st = state.ai.status.read().await.clone();
    let pct = if st.total_bytes > 0 { st.downloaded_bytes * 100 / st.total_bytes } else { 0 };
    match st.state.as_str() {
        "none" => "no AI model is set up on the server yet (an admin can pick one in Settings → AI Model)".into(),
        "downloading" => format!("the server is still downloading its AI model ({pct}%)"),
        "resolving" | "starting" => "the server's AI model is still loading; try again in a minute".into(),
        "error" => format!(
            "the server's AI model isn't running ({}). An admin can see details in Settings → AI Model",
            st.error.unwrap_or_else(|| "unknown error".into()).chars().take(200).collect::<String>()
        ),
        _ => "the server's AI model isn't available right now".into(),
    }
}

pub async fn maybe_respond(state: &Shared, ch: &Channel, row_id: &str, author_id: &str, content: &str, reply_to: Option<&str>) {
    if author_id == state.bot_id {
        return;
    }
    let triggered = match &ch.guild_id {
        None => {
            // DM that includes the bot
            sqlx::query_scalar::<_, i64>("SELECT 1 FROM dm_members WHERE channel_id = ? AND user_id = ?")
                .bind(&ch.id)
                .bind(&state.bot_id)
                .fetch_optional(&state.db)
                .await
                .ok()
                .flatten()
                .is_some()
        }
        Some(g) => {
            let s = settings(state, g).await;
            if !s.enabled {
                return;
            }
            let mention = content.contains(&format!("<@{}>", state.bot_id));
            let reply_to_bot = match reply_to {
                Some(r) => sqlx::query_scalar::<_, String>("SELECT author_id FROM messages WHERE id = ?")
                    .bind(r)
                    .fetch_optional(&state.db)
                    .await
                    .ok()
                    .flatten()
                    .map(|a| a == state.bot_id)
                    .unwrap_or(false),
                None => false,
            };
            mention || reply_to_bot || name_call_re(&state.s().bot_name).is_match(content) || s.always_channels.contains(&ch.id)
        }
    };
    if !triggered {
        return;
    }
    let st = state.clone();
    let ch = ch.clone();
    let trigger = row_id.to_string();
    tokio::spawn(async move {
        if let Err(e) = respond(st, ch, trigger).await {
            tracing::warn!("bot reply failed: {e:#}");
        }
    });
}

// ---------- prompt building ----------

fn civil_date(ms: i64) -> String {
    let days = ms.div_euclid(86_400_000);
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    format!("{y:04}-{m:02}-{d:02}")
}

async fn build_messages(state: &Shared, ch: &Channel, trigger: &str) -> anyhow::Result<Vec<Value>> {
    let mut rows = sqlx::query_as::<_, MessageRow>(&format!(
        "SELECT {MSG_COLS} FROM messages WHERE channel_id = ? AND id <= ? ORDER BY id DESC LIMIT 40"
    ))
    .bind(&ch.id)
    .bind(trigger)
    .fetch_all(&state.db)
    .await?;
    rows.reverse();
    let mut ids: Vec<String> = rows.iter().map(|r| r.author_id.clone()).collect();
    // a kid in the conversation (with kid-safe AI on) keeps the whole reply kid-appropriate
    let mut kid_present = false;
    for a in ids.iter().collect::<std::collections::HashSet<_>>() {
        if crate::kids::is_kid(state, a).await && crate::kids::settings(state, a).await.kid_safe_bot {
            kid_present = true;
        }
    }
    static MENTION: Lazy<Regex> = Lazy::new(|| Regex::new(r"<@([0-9a-z]{26})>").unwrap());
    for r in &rows {
        for c in MENTION.captures_iter(&r.content) {
            ids.push(c[1].to_string());
        }
    }
    ids.sort();
    ids.dedup();
    let users = load_users(&state.db, &ids).await?;
    let nick: std::collections::HashMap<String, String> = match &ch.guild_id {
        Some(g) => sqlx::query_as::<_, (String, String)>("SELECT user_id, nickname FROM members WHERE guild_id = ? AND nickname IS NOT NULL")
            .bind(g)
            .fetch_all(&state.db)
            .await?
            .into_iter()
            .collect(),
        None => Default::default(),
    };
    let name_of = |id: &str| -> String {
        nick.get(id).cloned().or_else(|| users.get(id).map(|u| u.display_name.clone())).unwrap_or_else(|| "someone".into())
    };

    let att_names: Vec<(String, String)> = {
        let mids: Vec<String> = rows.iter().map(|r| r.id.clone()).collect();
        if mids.is_empty() {
            vec![]
        } else {
            let q = format!(
                "SELECT ma.message_id, f.filename FROM message_attachments ma JOIN files f ON f.id = ma.file_id WHERE ma.message_id IN ({})",
                vec!["?"; mids.len()].join(",")
            );
            let mut qq = sqlx::query_as::<_, (String, String)>(&q);
            for m in &mids {
                qq = qq.bind(m);
            }
            qq.fetch_all(&state.db).await?
        }
    };

    let mut turns: Vec<(bool, String)> = vec![]; // (is_assistant, text)
    for r in &rows {
        let text = MENTION.replace_all(&r.content, |c: &regex::Captures| format!("@{}", name_of(&c[1]))).to_string();
        let files: Vec<&str> = att_names.iter().filter(|(m, _)| m == &r.id).map(|(_, f)| f.as_str()).collect();
        let mut body = text;
        if !files.is_empty() {
            body.push_str(&format!(" [attached: {}]", files.join(", ")));
        }
        if r.author_id == state.bot_id {
            turns.push((true, body));
        } else {
            turns.push((false, format!("{}: {}", name_of(&r.author_id), body)));
        }
    }
    // trim to a char budget from the end
    let mut budget = 14_000usize;
    let mut kept: Vec<(bool, String)> = vec![];
    for t in turns.into_iter().rev() {
        if t.1.len() > budget && !kept.is_empty() {
            break;
        }
        budget = budget.saturating_sub(t.1.len());
        kept.push(t);
    }
    kept.reverse();
    // merge consecutive same-role turns; must start with a user turn (strict chat templates)
    let mut merged: Vec<(bool, String)> = vec![];
    for (a, t) in kept {
        match merged.last_mut() {
            Some((la, lt)) if *la == a => {
                lt.push('\n');
                lt.push_str(&t);
            }
            _ => merged.push((a, t)),
        }
    }
    while matches!(merged.first(), Some((true, _))) {
        merged.remove(0);
    }

    let bot = &state.s().bot_name;
    let place = match &ch.guild_id {
        Some(g) => {
            let gname: String = sqlx::query_scalar("SELECT name FROM guilds WHERE id = ?").bind(g).fetch_one(&state.db).await?;
            format!(" in the server \"{gname}\", channel #{}", ch.name)
        }
        None => " in a direct message".to_string(),
    };
    let custom = match &ch.guild_id {
        Some(g) => settings(state, g).await.system_prompt,
        None => String::new(),
    };
    let mut system = format!(
        "You are {bot}, an AI assistant participating in a group chat on a private, self-hosted chat server{place}. \
         Each human message is prefixed with the sender's name, like \"Name: message\". \
         Reply naturally and conversationally as {bot}. Do NOT prefix your reply with your own name. \
         Keep replies concise unless asked for detail. You can use Discord-style markdown (**bold**, `code`, ```code blocks```). \
         Today's date is {}.",
        civil_date(now_ms())
    );
    if !custom.trim().is_empty() {
        system.push_str("\n\n");
        system.push_str(custom.trim());
    }
    if kid_present {
        system.push_str("\n\n");
        system.push_str(crate::kids::KID_SAFE_PROMPT);
    }
    let mut out = vec![json!({ "role": "system", "content": system })];
    for (a, t) in merged {
        out.push(json!({ "role": if a { "assistant" } else { "user" }, "content": t }));
    }
    Ok(out)
}

// ---------- generation ----------

/// Strip reasoning blocks (<think>…</think>) and a leading "Name:" the model may echo.
fn visible_text(raw: &str, bot: &str) -> String {
    let mut s = String::new();
    let mut rest = raw;
    loop {
        match rest.find("<think>") {
            Some(i) => {
                s.push_str(&rest[..i]);
                match rest[i..].find("</think>") {
                    Some(j) => rest = &rest[i + j + "</think>".len()..],
                    None => break, // still thinking
                }
            }
            None => {
                s.push_str(rest);
                break;
            }
        }
    }
    let t = s.trim_start();
    let prefix = format!("{bot}:");
    let t = t.strip_prefix(&prefix).unwrap_or(t);
    t.trim().chars().take(4000).collect()
}

struct Writer {
    state: Shared,
    ch: Channel,
    reply_to: String,
    raw: String,
    message_id: Option<String>,
    last_flush: Instant,
    last_sent: String,
    /// collect the reply without posting it (voice answers)
    silent: bool,
    /// tools the model asked for in this round
    tool_calls: Vec<Value>,
}

impl Writer {
    async fn push(&mut self, chunk: &str) {
        self.raw.push_str(chunk);
        if self.last_flush.elapsed() > Duration::from_millis(650) {
            self.flush().await;
        }
    }

    async fn flush(&mut self) {
        if self.silent {
            return;
        }
        let text = visible_text(&self.raw, &self.state.s().bot_name);
        if text.is_empty() || text == self.last_sent {
            return;
        }
        self.last_flush = Instant::now();
        let db = &self.state.db;
        match &self.message_id {
            None => {
                let id = new_id();
                if sqlx::query("INSERT INTO messages (id, channel_id, author_id, content, reply_to, created_at) VALUES (?,?,?,?,?,?)")
                    .bind(&id).bind(&self.ch.id).bind(&self.state.bot_id).bind(&text).bind(&self.reply_to).bind(now_ms())
                    .execute(db).await.is_err()
                {
                    return;
                }
                if let Ok(m) = load_message(db, &id).await {
                    let mut v = serde_json::to_value(&m).unwrap();
                    v["guild_id"] = json!(self.ch.guild_id);
                    v["streaming"] = json!(true);
                    self.state.emit_channel(&self.ch, "MESSAGE_CREATE", &v).await;
                }
                self.message_id = Some(id);
            }
            Some(id) => {
                let _ = sqlx::query("UPDATE messages SET content = ? WHERE id = ?").bind(&text).bind(id).execute(db).await;
                if let Ok(m) = load_message(db, id).await {
                    self.state.emit_channel(&self.ch, "MESSAGE_UPDATE", &m).await;
                }
            }
        }
        self.last_sent = text;
    }
}

enum Outcome {
    Finished,
    /// failed before producing any text — safe to try another backend
    FailedClean(String),
    /// failed mid-reply
    FailedPartial(String),
}

async fn drain(rx: &mut UnboundedReceiver<JobMsg>, w: &mut Writer) -> Outcome {
    let mut got_any = false;
    let started = Instant::now();
    loop {
        // generous first-token wait (model may be loading), then a stall timeout
        let wait = if got_any { Duration::from_secs(60) } else { Duration::from_secs(120) };
        if started.elapsed() > Duration::from_secs(600) {
            return Outcome::FailedPartial("took too long".into());
        }
        match tokio::time::timeout(wait, rx.recv()).await {
            Ok(Some(JobMsg::Chunk(c))) => {
                if !c.is_empty() {
                    got_any = true;
                }
                w.push(&c).await;
            }
            Ok(Some(JobMsg::Tools(calls))) => {
                got_any = true;
                w.tool_calls = calls;
            }
            Ok(Some(JobMsg::Done)) => return Outcome::Finished,
            Ok(Some(JobMsg::Error(e))) => return if got_any { Outcome::FailedPartial(e) } else { Outcome::FailedClean(e) },
            Ok(None) => return if got_any { Outcome::Finished } else { Outcome::FailedClean("closed".into()) },
            Err(_) => return if got_any { Outcome::FailedPartial("stalled".into()) } else { Outcome::FailedClean("timed out".into()) },
        }
    }
}

async fn eligible_workers(state: &Shared, ch: &Channel) -> Vec<u64> {
    let mut list: Vec<(u64, i64, usize, String)> = state
        .bot
        .workers
        .iter()
        .filter(|w| w.available)
        .map(|w| (*w.key(), w.vram_mb, w.active, w.user_id.clone()))
        .collect();
    // best GPU (most VRAM) first; a busy GPU drops behind idle ones
    list.sort_by(|a, b| (a.2 > 0).cmp(&(b.2 > 0)).then(b.1.cmp(&a.1)));
    let mut out = vec![];
    for (conn, _, _, uid) in list {
        // privacy: a lent GPU only ever sees channels its owner can already read
        let ok = perms::channel_perms(&state.db, ch, &uid).await.map(|p| p & perms::VIEW != 0).unwrap_or(false);
        if ok && worker_eligible(state, &uid).await {
            out.push(conn);
        }
    }
    out
}

async fn run_on_worker(state: &Shared, conn: u64, messages: &[Value], tools: &[Value], w: &mut Writer) -> Outcome {
    let job_id = new_id();
    let (tx, mut rx) = unbounded_channel();
    let sent = {
        let Some(mut worker) = state.bot.workers.get_mut(&conn) else { return Outcome::FailedClean("gone".into()) };
        worker.active += 1;
        state.bot.jobs.insert(job_id.clone(), (conn, tx));
        worker
            .tx
            .send(json!({ "t": "BOT_JOB", "d": {
                "job_id": job_id,
                "messages": messages,
                "tools": tools,
                "max_tokens": state.cfg.bot_max_tokens,
                "temperature": 0.7,
            }}).to_string())
            .is_ok()
    };
    let out = if sent { drain(&mut rx, w).await } else { Outcome::FailedClean("send failed".into()) };
    state.bot.jobs.remove(&job_id);
    if let Some(mut wk) = state.bot.workers.get_mut(&conn) {
        wk.active = wk.active.saturating_sub(1);
    }
    out
}

async fn run_on_server(state: &Shared, url: &str, messages: &[Value], tools: &[Value], w: &mut Writer) -> Outcome {
    let (tx, mut rx) = unbounded_channel();
    let mut body = json!({
        "model": "llamble",
        "messages": messages,
        "stream": true,
        "max_tokens": state.cfg.bot_max_tokens,
        "temperature": 0.7,
        "cache_prompt": true,
    });
    if !tools.is_empty() {
        body["tools"] = json!(tools);
    }
    let url = format!("{url}/v1/chat/completions");
    let task = tokio::spawn(async move {
        let client = reqwest::Client::builder().connect_timeout(Duration::from_secs(5)).build().unwrap();
        let res = match client.post(&url).json(&body).send().await {
            Ok(r) if r.status().is_success() => r,
            Ok(r) => {
                let _ = tx.send(JobMsg::Error(format!("llama server returned {}", r.status())));
                return;
            }
            Err(e) => {
                let _ = tx.send(JobMsg::Error(format!("llama server unreachable: {e}")));
                return;
            }
        };
        let _ = forward_sse(res, &tx).await;
        let _ = tx.send(JobMsg::Done);
    });
    let out = drain(&mut rx, w).await;
    task.abort();
    out
}

async fn forward_sse(res: reqwest::Response, tx: &UnboundedSender<JobMsg>) -> anyhow::Result<()> {
    let mut stream = res.bytes_stream();
    let mut buf = String::new();
    // tool calls arrive in pieces: index → {id, name, arguments}
    let mut calls: Vec<(String, String, String)> = vec![];
    let flush_calls = |calls: &Vec<(String, String, String)>| {
        if !calls.is_empty() {
            let v: Vec<Value> = calls.iter().map(|(id, n, a)| json!({ "id": id, "type": "function", "function": { "name": n, "arguments": a } })).collect();
            let _ = tx.send(JobMsg::Tools(v));
        }
    };
    while let Some(chunk) = stream.next().await {
        buf.push_str(&String::from_utf8_lossy(&chunk?));
        while let Some(i) = buf.find('\n') {
            let line = buf[..i].trim().to_string();
            buf.drain(..=i);
            let Some(data) = line.strip_prefix("data:") else { continue };
            let data = data.trim();
            if data == "[DONE]" {
                flush_calls(&calls);
                return Ok(());
            }
            if let Ok(v) = serde_json::from_str::<Value>(data) {
                let delta = &v["choices"][0]["delta"];
                if let Some(t) = delta["content"].as_str() {
                    let _ = tx.send(JobMsg::Chunk(t.to_string()));
                }
                for tc in delta["tool_calls"].as_array().into_iter().flatten() {
                    let i = tc["index"].as_u64().unwrap_or(calls.len() as u64) as usize;
                    while calls.len() <= i {
                        calls.push(Default::default());
                    }
                    if let Some(id) = tc["id"].as_str() {
                        calls[i].0 = id.to_string();
                    }
                    if let Some(n) = tc["function"]["name"].as_str() {
                        calls[i].1.push_str(n);
                    }
                    if let Some(a) = tc["function"]["arguments"].as_str() {
                        calls[i].2.push_str(a);
                    }
                }
            }
        }
    }
    flush_calls(&calls);
    Ok(())
}

/// Ask the best available model, running any tools it asks for (a few rounds at most).
/// `None` = no model anywhere.
async fn generate(state: &Shared, ch: &Channel, mut messages: Vec<Value>, w: &mut Writer, ctx: &crate::tools::Ctx) -> Option<Outcome> {
    let tools = crate::tools::definitions(state).await;
    for round in 0..4 {
        // last round: no tools, so it has to answer
        let offer: &[Value] = if round == 3 { &[] } else { &tools };
        w.tool_calls.clear();
        let mut result: Option<Outcome> = None;
        for conn in eligible_workers(state, ch).await {
            match run_on_worker(state, conn, &messages, offer, w).await {
                Outcome::FailedClean(e) => {
                    tracing::info!("worker {conn} failed ({e}); trying next backend");
                    continue;
                }
                o => {
                    result = Some(o);
                    break;
                }
            }
        }
        if result.is_none() {
            // right after a restart or update the server's model takes a minute to load: wait for it
            let mut waited = 0;
            while crate::ai::server_llama_url(state).await.is_none() && waited < 180 {
                let st = state.ai.status.read().await.state.clone();
                if !matches!(st.as_str(), "resolving" | "downloading" | "starting") {
                    break;
                }
                tokio::time::sleep(Duration::from_secs(2)).await;
                waited += 2;
            }
            if let Some(url) = crate::ai::server_llama_url(state).await {
                result = Some(run_on_server(state, &url, &messages, offer, w).await);
            }
        }
        let calls = std::mem::take(&mut w.tool_calls);
        match result {
            Some(Outcome::Finished) if !calls.is_empty() => {
                messages.push(json!({ "role": "assistant", "content": "", "tool_calls": calls }));
                for c in &calls {
                    let name = c["function"]["name"].as_str().unwrap_or("");
                    let args: Value = serde_json::from_str(c["function"]["arguments"].as_str().unwrap_or("{}")).unwrap_or(json!({}));
                    tracing::info!("bot tool: {name}");
                    let out = crate::tools::run(state, ctx, name, &args).await;
                    messages.push(json!({ "role": "tool", "tool_call_id": c["id"], "name": name, "content": out }));
                }
                continue;
            }
            other => return other,
        }
    }
    Some(Outcome::FailedPartial("too many tool rounds".into()))
}

async fn respond(state: Shared, ch: Channel, trigger: String) -> anyhow::Result<()> {
    let lock = state.bot.channel_locks.entry(ch.id.clone()).or_default().clone();
    let _guard = lock.lock().await;

    // typing indicator while we work
    let typing = {
        let st = state.clone();
        let ch2 = ch.clone();
        tokio::spawn(async move {
            loop {
                st.emit_channel(&ch2, "TYPING_START", &json!({ "channel_id": ch2.id, "user_id": st.bot_id, "ts": now_ms() })).await;
                tokio::time::sleep(Duration::from_secs(8)).await;
            }
        })
    };

    let messages = build_messages(&state, &ch, &trigger).await?;
    let mut w = Writer {
        state: state.clone(),
        ch: ch.clone(),
        reply_to: trigger.clone(),
        raw: String::new(),
        message_id: None,
        last_flush: Instant::now(),
        last_sent: String::new(),
        silent: false,
        tool_calls: vec![],
    };

    let author: Option<String> = sqlx::query_scalar("SELECT author_id FROM messages WHERE id = ?").bind(&trigger).fetch_optional(&state.db).await.ok().flatten();
    let ctx = crate::tools::Ctx {
        tz: author.as_ref().and_then(|a| USER_TZ.get(a).map(|t| t.clone())),
        kid: match &author {
            Some(a) => crate::kids::is_kid(&state, a).await,
            None => false,
        },
    };
    let result = generate(&state, &ch, messages, &mut w, &ctx).await;
    typing.abort();
    w.flush().await;

    match result {
        Some(Outcome::Finished) if w.message_id.is_some() => {}
        Some(Outcome::FailedPartial(e)) => {
            w.raw.push_str(&format!("\n\n*(reply cut off: {e})*"));
            w.flush().await;
        }
        other => {
            let why = match other {
                None => server_model_problem(&state).await,
                Some(Outcome::FailedClean(e)) => e,
                _ => "the model returned an empty reply".to_string(),
            };
            w.raw = format!("*I can't answer right now: {why}.*");
            w.flush().await;
        }
    }
    // let clients clear the typing indicator immediately
    state.emit_channel(&ch, "TYPING_STOP", &json!({ "channel_id": ch.id, "user_id": state.bot_id })).await;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn think_strip() {
        assert_eq!(visible_text("<think>hmm</think>Hello", "Llamble"), "Hello");
        assert_eq!(visible_text("<think>still going", "Llamble"), "");
        assert_eq!(visible_text("Llamble: hi there", "Llamble"), "hi there");
    }
    #[test]
    fn name_call() {
        let re = name_call_re("Llamble");
        assert!(re.is_match("llamble, what time is it"));
        assert!(re.is_match("hey Llamble how are you"));
        assert!(!re.is_match("we should llamble later"));
    }
    #[test]
    fn date() {
        assert_eq!(civil_date(0), "1970-01-01");
        assert_eq!(civil_date(1_762_473_600_000), "2025-11-07");
    }
}

/// Run a prompt on the best available model (a lent GPU whose owner can see `ch`, else the
/// server's own) and return the whole reply. Used for spoken answers in voice channels.
pub async fn complete(state: &Shared, ch: &Channel, messages: &[Value], ctx: &crate::tools::Ctx) -> anyhow::Result<String> {
    let mut w = Writer {
        state: state.clone(),
        ch: ch.clone(),
        reply_to: String::new(),
        raw: String::new(),
        message_id: None,
        last_flush: Instant::now(),
        last_sent: String::new(),
        silent: true,
        tool_calls: vec![],
    };
    let result = generate(state, ch, messages.to_vec(), &mut w, ctx).await;
    let text = visible_text(&w.raw, &state.s().bot_name);
    match result {
        Some(Outcome::Finished) | Some(Outcome::FailedPartial(_)) if !text.is_empty() => Ok(text),
        None => anyhow::bail!("{}", server_model_problem(state).await),
        Some(Outcome::FailedClean(e)) | Some(Outcome::FailedPartial(e)) => anyhow::bail!("{e}"),
        _ => anyhow::bail!("the model returned an empty reply"),
    }
}
